 "content": "def transform(grid):
    """Extend sparse interior marks between matching colored edge bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    edge_colors = [c for c in colors if c != bg]
    # Locate matching runs on opposite sides; the longest equal-length pair
    # identifies the bar axis and the offset correspondence.
    candidates = []
    for c in edge_colors:
        top = [j for j, v in enumerate(grid[0]) if v == c]
        bottom = [j for j, v in enumerate(grid[-1]) if v == c]
        if top and bottom and len(top) == len(bottom):
            candidates.append((len(top), 'tb', c, min(top), min(bottom)))
        left = [i for i in range(h) if grid[i][0] == c]
        right = [i for i in range(h) if grid[i][-1] == c]
        if left and right and len(left) == len(right):
            candidates.append((len(left), 'lr', c, min(left), min(right)))
    if not candidates:
        return out
    _, axis, bar, a0, b0 = max(candidates)
    # The remaining non-background color is the sparse mark/beam color.
    freq = {c: sum(row.count(c) for row in grid) for c in colors}
    mark = min((c for c in colors if c != bg and c != bar), key=lambda c: freq[c], default=None)
    if mark is None:
        return out
    marks = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == mark]
    if axis == 'tb':
        top_cols = [j for j, v in enumerate(grid[0]) if v == bar]
        bot_cols = [j for j, v in enumerate(grid[-1]) if v == bar]
        top_start, bot_start = min(top_cols), min(bot_cols)
        n = min(len(top_cols), len(bot_cols))
        for r, c in marks:
            if bot_start <= c < bot_start + n:
                k = c - bot_start
                # Project each selected offset through the opposite edge pair.
                tc = top_start + k
                for rr in range(1, h):
                    if grid[rr][tc] == bg or grid[rr][tc] == mark:
                        out[rr][tc] = mark
                # Extend the original clue toward its aligned bottom edge.
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg or grid[rr][c] == mark:
                        out[rr][c] = mark
                out[r][c] = 4
            elif top_start <= c < top_start + n:
                k = c - top_start
                bc = bot_start + k
                for rr in range(1, h - 1):
                    if grid[rr][bc] == bg or grid[rr][bc] == mark:
                        out[rr][bc] = mark
                for rr in range(r - 1, 0, -1):
                    if grid[rr][c] == bg or grid[rr][c] == mark:
                        out[rr][c] = mark
                out[r][c] = 4
    else:
        left_rows = [i for i in range(h) if grid[i][0] == bar]
        right_rows = [i for i in range(h) if grid[i][-1] == bar]
        left_start, right_start = min(left_rows), min(right_rows)
        n = min(len(left_rows), len(right_rows))
        for r, c in marks:
            if left_start <= r < left_start + n:
                k = r - left_start
                rr = right_start + k
                for cc in range(1, w - 1):
                    if grid[rr][cc] == bg or grid[rr][cc] == mark:
                        out[rr][cc] = mark
                for cc in range(1, c):
                    if grid[r][cc] == bg or grid[r][cc] == mark:
                        out[r][cc] = mark
                out[r][c] = 4
            elif right_start <= r < right_start + n:
                k = r - right_start
                rr = left_start + k
                for cc in range(1, w - 1):
                    if grid[rr][cc] == bg or grid[rr][cc] == mark:
                        out[rr][cc] = mark
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] == bg or grid[r][cc] == mark:
                        out[r][cc] = mark
                out[r][c] = 4
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
