 "content": "def _runs(values, color):
    runs = []
    start = None
    for i, value in enumerate(values + [None]):
        if value == color:
            if start is None:
                start = i
        elif start is not None:
            runs.append((start, i))
            start = None
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find equal-length, same-color bars on opposite borders.
    candidates = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    candidates.append((b - a, 'tb', color, a, c))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b - a, 'lr', color, a, c))
    if not candidates:
        return out
    _, orientation, bar_color, start_a, start_b = max(candidates)

    mark_colors = [c for c in counts if c not in (background, bar_color)]
    if not mark_colors:
        return out
    mark_color = min(mark_colors, key=lambda c: counts[c])
    marks = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == mark_color]

    if orientation == 'tb':
        top = _runs(grid[0], bar_color)
        bottom = _runs(grid[-1], bar_color)
        # Use the selected matching run pair, ordered by their positions.
        pairs = [(a, b, c, d) for a, b in top for c, d in bottom
                 if b - a == d - c]
        a, b, c, d = max(pairs, key=lambda p: p[1] - p[0])
        length = b - a
        for r, col in marks:
            if a <= col < b:
                offset = col - a
                # Direct ray from the clue to the bar on its own side.
                for rr in range(1, r):
                    if grid[rr][col] in (background, mark_color):
                        out[rr][col] = mark_color
                # Matching offset on the opposite border projects through the grid.
                projected = c + offset
                for rr in range(1, h - 1):
                    if grid[rr][projected] in (background, mark_color):
                        out[rr][projected] = mark_color
            elif c <= col < d:
                offset = col - c
                for rr in range(r + 1, h - 1):
                    if grid[rr][col] in (background, mark_color):
                        out[rr][col] = mark_color
                projected = a + offset
                for rr in range(1, h - 1):
                    if grid[rr][projected] in (background, mark_color):
                        out[rr][projected] = mark_color
    else:
        left = _runs([grid[r][0] for r in range(h)], bar_color)
        right = _runs([grid[r][-1] for r in range(h)], bar_color)
        pairs = [(a, b, c, d) for a, b in left for c, d in right
                 if b - a == d - c]
        a, b, c, d = max(pairs, key=lambda p: p[1] - p[0])
        for r, col in marks:
            if a <= r < b:
                offset = r - a
                for cc in range(1, col):
                    if grid[r][cc] in (background, mark_color):
                        out[r][cc] = mark_color
                projected = c + offset
                for cc in range(1, w - 1):
                    if grid[projected][cc] in (background, mark_color):
                        out[projected][cc] = mark_color
            elif c <= r < d:
                offset = r - c
                for cc in range(col + 1, w - 1):
                    if grid[r][cc] in (background, mark_color):
                        out[r][cc] = mark_color
                projected = a + offset
                for cc in range(1, w - 1):
                    if grid[projected][cc] in (background, mark_color):
                        out[projected][cc] = mark_color

    # Original clue points mark the ends of rays.
    for r, c in marks:
        out[r][c] = 4
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
