 "content": "def _runs(values, color):
    result = []
    start = None
    for i, value in enumerate(values + [None]):
        if value == color:
            if start is None:
                start = i
        elif start is not None:
            result.append((start, i))
            start = None
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # Paired equal-size bars of a shared color lie on opposite grid edges.
    candidates = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    candidates.append((b - a, 'tb', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b - a, 'lr', color, a, b, c, d))
    if not candidates:
        return out
    _, orientation, bar_color, a, b, c, d = max(candidates)
    marker_colors = [color for color in counts
                     if color not in (background, bar_color)]
    if not marker_colors:
        return out
    marker_color = min(marker_colors, key=lambda color: counts[color])
    marks = [(r, col) for r in range(h) for col in range(w)
             if grid[r][col] == marker_color]

    if orientation == 'tb':
        # For each clue within one edge-bar's span, paint a full column both
        # at its own offset and at the matching offset of the opposite bar.
        top_runs = _runs(grid[0], bar_color)
        bottom_runs = _runs(grid[-1], bar_color)
        pairs = [(u, v, x, y) for u, v in top_runs for x, y in bottom_runs
                 if v - u == y - x]
        u, v, x, y = max(pairs, key=lambda p: p[1] - p[0])
        for r, col in marks:
            target = None
            if u <= col < v:
                target = x + (col - u)
            elif x <= col < y:
                target = u + (col - x)
            if target is None:
                continue
            for cc in (col, target):
                for rr in range(h):
                    if grid[rr][cc] in (background, marker_color):
                        out[rr][cc] = marker_color
    else:
        left_runs = _runs([grid[r][0] for r in range(h)], bar_color)
        right_runs = _runs([grid[r][-1] for r in range(h)], bar_color)
        pairs = [(u, v, x, y) for u, v in left_runs for x, y in right_runs
                 if v - u == y - x]
        u, v, x, y = max(pairs, key=lambda p: p[1] - p[0])
        for r, col in marks:
            target = None
            if u <= r < v:
                target = x + (r - u)
            elif x <= r < y:
                target = u + (r - x)
            if target is None:
                continue
            for rr in (r, target):
                for cc in range(w):
                    if grid[rr][cc] in (background, marker_color):
                        out[rr][cc] = marker_color

    # Clue cells are encoded as endpoints; fill stripes remain otherwise intact.
    for r, col in marks:
        out[r][col] = 4
    return out


