def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # The two boundary bars have the same color and length.
    candidates = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    candidates.append((b - a, 'tb', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b - a, 'lr', color, a, b, c, d))
    if not candidates:
        return out
    _, axis, frame, a, b, c, d = max(candidates)

    marker_colors = [color for color in counts if color not in (background, frame)]
    if not marker_colors:
        return out
    marker = min(marker_colors, key=lambda color: counts[color])
    marks = [(r, col) for r in range(h) for col in range(w)
             if grid[r][col] == marker]

    if axis == 'tb':
        # A clue aligned with either horizontal bar sends a ray toward that
        # bar, while its offset is projected through the opposite side.
        for r, col in marks:
            if a <= col < b:
                target = c + (col - a)
                direct_rows = range(1, r)
            elif c <= col < d:
                target = a + (col - c)
                direct_rows = range(r + 1, h - 1)
            else:
                continue
            for rr in direct_rows:
                if grid[rr][col] == background:
                    out[rr][col] = marker
            # Projection spans the whole grid, stopping naturally at the
            # colored edge bars and preserving all non-background cells.
            for rr in range(h):
                if grid[rr][target] == background:
                    out[rr][target] = marker
    else:
        # Transposed construction for vertical bars on the left and right.
        for r, col in marks:
            if a <= r < b:
                target = c + (r - a)
                direct_cols = range(1, col)
            elif c <= r < d:
                target = a + (r - c)
                direct_cols = range(col + 1, w - 1)
            else:
                continue
            for cc in direct_cols:
                if grid[r][cc] == background:
                    out[r][cc] = marker
            for cc in range(w):
                if grid[target][cc] == background:
                    out[target][cc] = marker

    # Every original clue is the endpoint of a ray.
    for r, col in marks:
        out[r][col] = 4
    return out


